extends Node3D
class_name TunisStreetLifePass

const PROFILE_PATH := "res://data/art/tunis_art_profile.json"

var generated_count := 0
var profile: Dictionary = {}
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _load_profile()
    _build_parked_scooters()
    _build_shopfront_clutter()
    _build_planters()
    _build_waste_bins()
    _build_utility_cables()


func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    var show_medium := current_detail_level >= 1
    var show_high := current_detail_level >= 2
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_medium
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_high

func _register_detail(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
        node.visible = current_detail_level >= 2
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
        node.visible = current_detail_level >= 1
    return node

func _load_profile() -> void:
    if not FileAccess.file_exists(PROFILE_PATH):
        return
    var file := FileAccess.open(PROFILE_PATH, FileAccess.READ)
    if file == null:
        return
    var parsed = JSON.parse_string(file.get_as_text())
    if typeof(parsed) == TYPE_DICTIONARY:
        profile = parsed

func _material(color: Color, roughness := 0.82, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    add_child(instance)
    generated_count += 1
    return instance

func _cylinder(pos: Vector3, radius: float, height: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := CylinderMesh.new()
    mesh.top_radius = radius
    mesh.bottom_radius = radius
    mesh.height = height
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    add_child(instance)
    generated_count += 1
    return instance

func _build_parked_scooters() -> void:
    var positions := [
        Vector3(-57.0, 0.48, -63.2),
        Vector3(-53.7, 0.48, -63.1),
        Vector3(22.5, 0.48, -63.0),
        Vector3(35.0, 0.48, 52.0),
        Vector3(39.0, 0.48, 51.8)
    ]
    var body_colors := [Color("#8f2727"), Color("#263d55"), Color("#d0c4a5")]
    for i in range(positions.size()):
        var root := Node3D.new()
        root.position = positions[i]
        root.rotation_degrees.y = -8.0 + float(i % 3) * 14.0
        add_child(root)
        _register_detail(root, 1)
        _scooter(root, body_colors[i % body_colors.size()])

func _scooter(parent: Node3D, body_color: Color) -> void:
    var body := MeshInstance3D.new()
    var body_mesh := BoxMesh.new()
    body_mesh.size = Vector3(0.42, 0.42, 1.25)
    body.mesh = body_mesh
    body.position = Vector3(0, 0.2, 0)
    body.material_override = _material(body_color, 0.72, 0.06)
    parent.add_child(body)
    generated_count += 1

    for z in [-0.48, 0.48]:
        var wheel := MeshInstance3D.new()
        var wheel_mesh := CylinderMesh.new()
        wheel_mesh.top_radius = 0.20
        wheel_mesh.bottom_radius = 0.20
        wheel_mesh.height = 0.11
        wheel.mesh = wheel_mesh
        wheel.position = Vector3(0, -0.12, z)
        wheel.rotation_degrees.z = 90.0
        wheel.material_override = _material(Color("#151719"), 0.92)
        parent.add_child(wheel)
        generated_count += 1

    var stem := MeshInstance3D.new()
    var stem_mesh := BoxMesh.new()
    stem_mesh.size = Vector3(0.07, 0.75, 0.07)
    stem.mesh = stem_mesh
    stem.position = Vector3(0, 0.64, 0.48)
    stem.rotation_degrees.x = -12.0
    stem.material_override = _material(Color("#3d4145"), 0.55, 0.35)
    parent.add_child(stem)
    generated_count += 1

func _build_shopfront_clutter() -> void:
    var crates := [
        Vector3(24.0,0.34,-64.1), Vector3(25.0,0.34,-64.0),
        Vector3(-43.5,0.34,-64.0), Vector3(-42.5,0.34,-64.0)
    ]
    for i in range(crates.size()):
        _register_detail(_box(crates[i], Vector3(0.78,0.62,0.58), Color("#3d6f8e") if i < 2 else Color("#9a6c32")), 2)

    for x in [-34.5, -33.4, -32.3]:
        _register_detail(_cylinder(Vector3(x,0.48,51.6), 0.31, 0.96, Color("#59636a")), 2)

    for x in [72.5, 74.0, 75.5]:
        _register_detail(_box(Vector3(x,0.46,-7.0), Vector3(1.05,0.88,0.72), Color("#d8d0b9")), 2)

func _build_planters() -> void:
    for pos in [Vector3(-12.0,0.42,-12.8), Vector3(12.0,0.42,-12.8), Vector3(-12.0,0.42,12.8), Vector3(12.0,0.42,12.8)]:
        _register_detail(_cylinder(pos, 0.42, 0.68, Color("#9b6a47")), 1)
        _register_detail(_cylinder(pos + Vector3(0,0.72,0), 0.24, 0.75, Color("#456b42")), 1)

func _build_waste_bins() -> void:
    for pos in [Vector3(-9.7,0.58,-28.0), Vector3(9.7,0.58,28.0), Vector3(53.0,0.58,9.6)]:
        _box(pos, Vector3(0.72,1.12,0.72), Color("#3b5b49"))
        _box(pos + Vector3(0,0.62,0), Vector3(0.78,0.12,0.78), Color("#252d29"))

func _build_utility_cables() -> void:
    var cable_color := Color("#202225")
    var spans := [
        [Vector3(-64,7.8,-67.0), Vector3(-25,7.2,-67.0)],
        [Vector3(20,8.0,-67.0), Vector3(63,7.4,-67.0)],
        [Vector3(-65,7.4,52.5), Vector3(-22,7.9,52.5)]
    ]
    for span in spans:
        var start: Vector3 = span[0]
        var finish: Vector3 = span[1]
        var segments := 10
        for i in range(segments):
            var t0 := float(i) / float(segments)
            var t1 := float(i + 1) / float(segments)
            var p0 := start.lerp(finish, t0)
            var p1 := start.lerp(finish, t1)
            p0.y -= sin(t0 * PI) * 0.65
            p1.y -= sin(t1 * PI) * 0.65
            _cable_segment(p0, p1, cable_color)

func _cable_segment(a: Vector3, b: Vector3, color: Color) -> void:
    var midpoint := (a + b) * 0.5
    var length := a.distance_to(b)
    var segment := _cylinder(midpoint, 0.025, length, color)
    _register_detail(segment, 2)
    segment.look_at(b, Vector3.UP)
    segment.rotate_object_local(Vector3.RIGHT, PI * 0.5)

