    _register(root, 1)
    for pos in [Vector3(-28.0, 0.26, -9.5), Vector3(-26.9, 0.26, -9.5), Vector3(36.0, 0.26, 9.6)]:
        _box(root, pos, Vector3(0.86, 0.48, 0.68), Color("#786143"))

func _build_cleaning_points() -> void:
    var root := Node3D.new()
    root.name = "StreetCleaningPoints"
    add_child(root)
    _register(root, 2)
    for x in [-18.0, 24.0]:
        _cylinder(root, Vector3(x, 0.46, 9.7), 0.09, 0.92, Color("#4b5658"))
        _box(root, Vector3(x + 0.42, 0.18, 9.7), Vector3(0.72, 0.12, 0.2), Color("#4b5658"))

