class_name TunisTransitPass

var generated_count := 0
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_bus_shelter()
    _build_taxi_rank()
    _build_lane_markers()
    _build_transit_furniture()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    var show_medium := current_detail_level >= 1
    var show_high := current_detail_level >= 2
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_medium
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_high

func _register_detail(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _material(color: Color, roughness := 0.82, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _cylinder(parent: Node3D, pos: Vector3, radius: float, height: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := CylinderMesh.new()
    mesh.top_radius = radius
    mesh.bottom_radius = radius
    mesh.height = height
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _label(parent: Node3D, pos: Vector3, text: String, pixel := 0.006) -> Label3D:
    var label := Label3D.new()
    label.position = pos
    label.text = text
    label.font_size = 48
    label.pixel_size = pixel
    label.outline_size = 7
    label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
    parent.add_child(label)
    generated_count += 1
    return label

func _build_bus_shelter() -> void:
    var root := Node3D.new()
    root.name = "TransitBusShelter"
    root.position = Vector3(-7.8, 0.0, 8.9)
    add_child(root)

    _box(root, Vector3(0, 1.65, 0.55), Vector3(5.6, 3.2, 0.12), Color("#60747c"))
    _box(root, Vector3(0, 3.25, 0.05), Vector3(6.0, 0.16, 1.45), Color("#d8d4c9"))
    _box(root, Vector3(0, 0.58, -0.05), Vector3(3.8, 0.16, 0.58), Color("#6e5541"))
    _label(root, Vector3(0, 2.72, -0.07), "حافلة · BUS", 0.0056)

    for x in [-2.55, 2.55]:
        _box(root, Vector3(x, 1.6, 0.02), Vector3(0.13, 3.1, 0.13), Color("#3d4549"))

    var route_panel := _box(root, Vector3(2.1, 1.7, -0.12), Vector3(0.78, 1.55, 0.08), Color("#24527a"))
    _register_detail(route_panel, 1)
    var route_label := _label(root, Vector3(2.1, 1.7, -0.18), "32\n71", 0.0046)
    _register_detail(route_label, 1)

func _build_taxi_rank() -> void:
    var root := Node3D.new()
    root.name = "TransitTaxiRank"
    root.position = Vector3(20.5, 0.0, -8.9)
    add_child(root)

    _cylinder(root, Vector3(0, 1.65, 0), 0.09, 3.3, Color("#3b3e40"))
    _box(root, Vector3(0, 3.05, 0), Vector3(2.7, 0.85, 0.12), Color("#f0d33e"))
    _label(root, Vector3(0, 3.05, -0.08), "TAXI · تاكسي", 0.0055)

    for i in range(4):
        var queue_marker := _box(root, Vector3(-4.2 + float(i) * 2.25, 0.11, -0.15), Vector3(1.5, 0.025, 0.16), Color("#e5d85a"))
        _register_detail(queue_marker, 1)

func _build_lane_markers() -> void:
    var root := Node3D.new()
    root.name = "TransitLaneMarkers"
    add_child(root)
    _register_detail(root, 1)

    for i in range(7):
        var x := -6.0 + float(i) * 2.0
        _box(root, Vector3(x, 0.125, 6.7), Vector3(1.1, 0.02, 0.12), Color("#e7d95d"))
    for i in range(6):
        var z := -6.0 + float(i) * 2.0
        var stud := _cylinder(root, Vector3(16.8, 0.15, z), 0.08, 0.04, Color("#d9d3bb"))
        _register_detail(stud, 2)

func _build_transit_furniture() -> void:
    var root := Node3D.new()
    root.name = "TransitStreetFurniture"
    add_child(root)

    for pos in [Vector3(-11.4, 0.46, 9.4), Vector3(-4.2, 0.46, 9.4)]:
        var bench := Node3D.new()
        bench.position = pos
        root.add_child(bench)
        _register_detail(bench, 1)
        _box(bench, Vector3.ZERO, Vector3(2.3, 0.16, 0.58), Color("#72523a"))
        _box(bench, Vector3(0, 0.7, 0.24), Vector3(2.3, 0.85, 0.12), Color("#72523a"))

    for x in [-13.2, -12.2, -3.4, -2.4]:
        var bollard := _cylinder(root, Vector3(x, 0.52, 7.8), 0.11, 1.04, Color("#303438"))
        _register_detail(bollard, 2)
